let pipelineState=null,pipelineRun=null,pipelineContract=null,pipelineFields=[];
const pipelineAction=(message,fn)=>run(message,fn,'pipeline-notice');
function pipelineSources(rows){const el=$('pipeline-source'),old=el.value;el.innerHTML='<option value="">Choose a CSV</option>'+rows.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');el.value=old;}
async function pipelineLists(){const rows=await api('/api/pipelines'),el=$('pipeline-list'),old=el.value;el.innerHTML='<option value="">Choose a pipeline</option>'+rows.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('');el.value=old;pipelineSources(await api('/api/datasets'));}
async function pipelineOpen(){
  if(!$('pipeline-list').value){pipelineState=null;pipelineContract=null;for(const id of ['pipeline-contract','pipeline-contract-detail','pipeline-history','pipeline-current'])$(id).innerHTML='';return;}
  pipelineState=await api('/api/pipeline/'+$('pipeline-list').value);const p=pipelineState;
  $('pipeline-name').value=p.name;$('pipeline-contract').innerHTML=p.contracts.map(c=>`<option value="${esc(c.id)}">Version ${c.version} · ${esc(c.created)}</option>`).join('');
  $('pipeline-history').innerHTML='<option value="">Choose a run</option>'+p.runs.map(r=>`<option value="${esc(r.id)}">${r.gate.passed?'PASSED':'BLOCKED'} · v${r.contract_version} · ${esc(r.source_name)} · ${esc(r.created)}</option>`).join('');
  $('pipeline-current').innerHTML=p.current?`<h3>Published snapshot</h3><p>Run ${esc(p.current.run_id)}<br>Published ${esc(p.current.created)} · <a href="/api/dataset-csv/${esc(p.current.dataset_id)}" download="published.csv">Download current CSV</a></p><details><summary>Publication lineage · ${p.publications.length} events</summary><pre>${esc(JSON.stringify(p.publications,null,2))}</pre></details>`:'<p>No published snapshot yet. Validate a batch, inspect its report, then publish.</p>';
  await pipelineReadContract();
}
async function pipelineReadContract(){if(!$('pipeline-contract').value)return;pipelineContract=await api('/api/pipeline-contract/'+$('pipeline-contract').value);$('pipeline-contract-detail').innerHTML=`<p>Version ${pipelineContract.version} · ${pipelineContract.spec.fields.length} columns · key: ${esc(pipelineContract.spec.key.join(' + '))}</p><details><summary>Contract rules and fingerprint</summary><pre>${esc(JSON.stringify({sha256:pipelineContract.spec_hash,...pipelineContract.spec},null,2))}</pre></details>`;}
function renderPipelineFields(){
  $('pipeline-fields').innerHTML='<div class="table-scroll"><table class="result-table"><thead><tr><th>Column</th><th>Type</th><th>Required</th><th>Unique key</th></tr></thead><tbody>'+pipelineFields.map((f,i)=>`<tr><td>${esc(f.name)}</td><td><select id="pipeline-type-${i}" aria-label="Type for ${esc(f.name)}">${['text','integer','decimal','date','boolean'].map(t=>`<option ${f.type===t?'selected':''}>${t}</option>`).join('')}</select></td><td><input type="checkbox" id="pipeline-required-${i}" aria-label="Required ${esc(f.name)}" ${f.required?'checked':''}></td><td><input type="checkbox" id="pipeline-key-${i}" aria-label="Key ${esc(f.name)}" ${f.key?'checked':''}></td></tr>`).join('')+'</tbody></table></div>';
}
function renderPipelineRun(){
  const r=pipelineRun,passed=r.gate.passed;$('pipeline-report').innerHTML=`<h3>${passed?'PASSED':'BLOCKED'} · ${esc(r.source_name)}</h3><p>Contract version ${r.contract_version} · ${esc(r.engine)} · ${esc(r.created)}</p><div class="stats">${Object.entries(r.counts).map(([k,v])=>`<div class="stat"><strong>${v}</strong><span>${esc(k)}</span></div>`).join('')}</div><p>${passed?'This run is eligible for publication, subject to the latest contract and current snapshot checks.':'Publication blocked. The previous published snapshot is unchanged.'}</p>${r.gate.reasons.map(reason=>`<p class="status-invalid">${esc(reason)}</p>`).join('')}<p>Gate: at most ${r.gate.max_quarantine_percent}% quarantine; at least ${r.gate.min_accepted_rows} accepted rows.</p><div class="detail-actions">${passed?'<button id="pipeline-publish" class="primary">Publish accepted snapshot</button>':''}<button id="pipeline-report-download">Download diagnostic JSON</button><a class="button" href="/api/pipeline-export/${esc(r.id)}/quarantine" download="quarantine.csv">Quarantine CSV</a>${passed?`<a class="button" href="/api/pipeline-export/${esc(r.id)}/accepted" download="accepted.csv">Accepted CSV</a>`:''}</div><p class="small">CSV downloads protect formula-like cells with an apostrophe. Stored snapshots and diagnostic JSON preserve original cell spelling. Decimal values in typed JSON are exact strings.</p><details><summary>Lineage and execution identity</summary><pre>${esc(JSON.stringify({run:r.id,pipeline:r.pipeline_id,contract:r.contract_id,contract_sha256:r.contract_sha256,source_sha256:r.source_sha256,error_counts:r.error_counts},null,2))}</pre></details><details><summary>Accepted rows · ${r.accepted.length}</summary><p>First 50 shown. Full diagnostic JSON contains every accepted and quarantined row.</p><pre>${esc(JSON.stringify(r.accepted.slice(0,50),null,2))}</pre></details><details ${passed?'':'open'}><summary>Quarantine reasons · ${r.quarantine.length}</summary>${r.quarantine.slice(0,100).map(x=>`<p><strong>Source record ${x.record}</strong> · ${esc(x.reasons.map(e=>(e.field?e.field+': ':'')+e.message).join(' '))}</p><pre>${esc(JSON.stringify(x.raw))}</pre>`).join('')}</details><p class="small">${esc(r.note)}</p>`;
  $('pipeline-report-download').onclick=()=>pipelineDownload(r,'validation-'+r.id+'.json');
  if(passed)$('pipeline-publish').onclick=()=>pipelineAction('Publishing a passing snapshot…',async()=>{if(!pipelineState||pipelineState.id!==r.pipeline_id)throw Error('Reopen this pipeline before publishing.');const result=await api('/api/pipeline-publish',{run_id:r.id,expected_current:pipelineState.current?.run_id??null});await pipelineOpen();await refreshDatasets();notice(result.reused?'This run is already the current snapshot. No new publication event.':'Published accepted rows. The previous snapshot remains in lineage.');});
}
function pipelineDownload(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('pipeline-list').onchange=()=>pipelineAction('Opening pipeline…',async()=>{pipelineRun=null;$('pipeline-report').innerHTML='';await pipelineOpen();notice('Select a pinned contract and a source batch.');});
$('pipeline-contract').onchange=()=>pipelineAction('Reading pinned contract…',async()=>{await pipelineReadContract();notice('Contract loaded. Existing runs are unchanged.');});
$('pipeline-fields-load').onclick=()=>pipelineAction('Preparing explicit field rules…',async()=>{if(!$('pipeline-source').value)throw Error('Choose a source CSV.');const d=await api('/api/dataset/'+$('pipeline-source').value);pipelineFields=d.report.columns.map(c=>({name:c.name,type:'text',required:true,key:false}));renderPipelineFields();notice('All types start as text. Choose types and at least one required unique-key field.');});
$('pipeline-contract-save').onclick=()=>pipelineAction('Saving immutable contract…',async()=>{if(!pipelineFields.length)throw Error('Load columns from a source CSV first.');const spec={fields:pipelineFields.map((f,i)=>({name:f.name,type:$('pipeline-type-'+i).value,required:$('pipeline-required-'+i).checked})),key:pipelineFields.filter((f,i)=>$('pipeline-key-'+i).checked).map(f=>f.name),max_quarantine_percent:Number($('pipeline-max-bad').value),min_accepted_rows:Number($('pipeline-min-rows').value)};const c=await api('/api/pipeline-contract',{name:$('pipeline-name').value,spec});await pipelineLists();$('pipeline-list').value=c.pipeline_id;await pipelineOpen();$('pipeline-contract').value=c.id;await pipelineReadContract();pipelineRun=null;$('pipeline-report').innerHTML='';notice('Contract saved. Identical rules reuse their existing version; previous versions remain available.');});
$('pipeline-run').onclick=()=>pipelineAction('Validating source against pinned contract…',async()=>{if(!$('pipeline-contract').value||!$('pipeline-source').value)throw Error('Choose a contract and a source batch.');pipelineRun=await api('/api/pipeline-run',{contract_id:$('pipeline-contract').value,dataset_id:$('pipeline-source').value});await pipelineOpen();$('pipeline-contract').value=pipelineRun.contract_id;await pipelineReadContract();$('pipeline-history').value=pipelineRun.id;renderPipelineRun();notice(pipelineRun.gate.passed?'Batch passed. Inspect the report before publishing.':'Batch blocked. Published data was not changed.');});
$('pipeline-history').onchange=()=>pipelineAction('Reopening validation result…',async()=>{if(!$('pipeline-history').value)return;pipelineRun=await api('/api/pipeline-run/'+$('pipeline-history').value);renderPipelineRun();notice('Saved result opened; no revalidation or publication occurred.');});
$('pipeline-download-contract').onclick=()=>{if(pipelineContract)pipelineDownload(pipelineContract.spec,'contract-v'+pipelineContract.version+'.json');};
$('pipeline-demo').onclick=()=>pipelineAction('Preparing passing and failing batches…',async()=>{const d=await api('/api/pipeline-demo',{});await pipelineLists();await refreshDatasets();$('pipeline-list').value=d.pipeline_id;await pipelineOpen();$('pipeline-contract').value=d.contract_id;await pipelineReadContract();$('pipeline-source').value=d.good;pipelineRun=null;$('pipeline-report').innerHTML='';notice('Demo ready: validate passing.csv and publish it; then choose failing.csv and validate. The failed batch must leave the published snapshot unchanged.');});
$('pipeline-save-source').onclick=()=>pipelineAction('Saving source batch…',async()=>{const f=$('pipeline-upload').files[0];if(!f)throw Error('Choose a CSV file.');if(f.size>2000000)throw Error('CSV exceeds 2 MB.');const d=await api('/api/dataset-save',{name:f.name,content:new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer())});await refreshDatasets();$('pipeline-source').value=d.id;notice('Source batch saved unchanged. Choose or create its contract.');});
document.addEventListener('datasets-updated',e=>pipelineSources(e.detail));
pipelineLists().catch(e=>{const el=$('pipeline-notice');el.className='notice error';el.textContent=e.message;});

$('pipeline-contract-edit').onclick=()=>pipelineAction('Loading pinned rules into editor…',async()=>{if(!pipelineContract)throw Error('Select a contract first.');const spec=pipelineContract.spec;pipelineFields=spec.fields.map(f=>({...f,key:spec.key.includes(f.name)}));$('pipeline-name').value=pipelineContract.name;$('pipeline-max-bad').value=spec.max_quarantine_percent;$('pipeline-min-rows').value=spec.min_accepted_rows;renderPipelineFields();notice('Edit a copy of these rules. Saving never changes the pinned version.');});
